import{d as g,C as o,o as h,c as d,j as i,a,E as e,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第11章","description":"《中庸》第 11 章——素隐行怪、半涂而废、依乎中庸：三种态度，一过一不及，唯依乎中庸者遁世不见知而不悔。","frontmatter":{"title":"中庸·第11章","description":"《中庸》第 11 章——素隐行怪、半涂而废、依乎中庸：三种态度，一过一不及，唯依乎中庸者遁世不见知而不悔。","category":"guide","aliases":["第11章","中庸第11章","素隐行怪"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-11.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-11.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-11.md"},f=g({...m,setup(p){const r=[{id:"suoyin",label:"素隐行怪 · 后世有述焉",showLabel:!0,sentences:[["子曰：“",{text:"素隐行怪",glossary:"suoyin"},"，后世有述焉，吾弗为之矣。"]],note:"「素隐行怪」（素，一说当作「索」；探求隐僻之理、做怪异之行），后世或许有人传述，但孔子说「吾弗为之矣」——我不做这种事。"},{id:"bantu",label:"遵道而行 · 半涂而废",showLabel:!0,sentences:[["君子遵道而行，",{text:"半涂而废",glossary:"bantu"},"，吾弗能",{text:"已",glossary:"yi"},"矣。"]],note:"「遵道而行，半涂而废」——遵循正道而行，却半路停下。孔子说「吾弗能已矣」——我不能就此罢手。"},{id:"yihu",label:"依乎中庸 · 遁世不见知而不悔",showLabel:!0,sentences:[["君子",{text:"依乎中庸",glossary:"yihu"},"，",{text:"遁世不见知而不悔",glossary:"dunshi"},"，唯圣者能之。”"]],note:"「君子依乎中庸，遁世不见知而不悔」——依循中庸而行，即使隐遁、不为人所知，也不后悔；这只有圣人才能做到。三句层层递进，以「唯圣者能之」收束全章。"}],s=[{id:"suoyin",term:"素隐行怪",pinyin:"suǒ yǐn xíng guài",meaning:"朱注：「素，按《汉书》当作索，盖字之误也。」索隐行怪：深求隐僻之理，而过为诡异之行。朱注谓此「知之过而不择乎善，行之过而不用其中」。"},{id:"bantu",term:"半涂而废",pinyin:"bàn tú ér fèi",meaning:"半路停下。涂：同「途」。朱注：「遵道而行，则能择乎善矣；半涂而废，则力之不足也。」"},{id:"yi",term:"已",pinyin:"yǐ",meaning:"止、停止。朱注：「圣人于此，非勉焉而不敢废，盖至诚无息，自有所不能止也。」"},{id:"yihu",term:"依乎中庸",pinyin:"yī hū zhōng yōng",meaning:"依循中庸而行。朱注：「不为索隐行怪，则依乎中庸而已。」"},{id:"dunshi",term:"遁世不见知而不悔",pinyin:"dùn shì bù xiàn zhī ér bù huǐ",meaning:"避世而不被人知道，也不后悔。见：被。朱注以此为「中庸之成德，知之尽、仁之至、不赖勇而裕如者」。"}];return(y,n)=>{const l=o("DaoTextReading"),t=o("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第11章",tabindex:"-1"},[a("中庸·第11章 "),i("a",{class:"header-anchor",href:"#中庸·第11章","aria-label":'Permalink to "中庸·第11章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第十一章摆出三种态度："),i("strong",null,"索隐行怪"),a("（过）、"),i("strong",null,"半涂而废"),a("（不及）、"),i("strong",null,"依乎中庸"),a("（正）。前两种正是第四章「过与不及」的具体样子。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),e(l,{colophon:"素隐行怪 · 半涂而废 · 依乎中庸",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第11章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(t,{items:[{term:"素隐行怪",pinyin:["suǒ","yǐn","xíng","guài"],meaning:"朱注：素当作「索」。索隐行怪：深求隐僻之理，过为诡异之行。"},{term:"半涂而废",pinyin:["bàn","tú","ér","fèi"],meaning:"半路停下。涂：同「途」。"},{term:"已",pinyin:["yǐ"],meaning:"止、停止。"},{term:"依乎中庸",pinyin:["yī","hū","zhōng","yōng"],meaning:"依循中庸而行。"},{term:"遁世不见知而不悔",pinyin:["dùn","shì","bù","xiàn","zhī","ér","bù","huǐ"],meaning:"避世而不被了解，也不后悔。见：被。"}]}),e(t,{items:[{term:"不当强而强",pinyin:["bù","dāng","qiáng","ér","qiáng"],meaning:"朱注的判语：索隐行怪是「不当强而强」——该松手时用力。"},{term:"当强而不强",pinyin:["dāng","qiáng","ér","bù","qiáng"],meaning:"朱注的判语：半涂而废是「当强而不强」——该坚持时松手。一过一不及，正与第四章相应。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>素隐行怪 · 后世有述焉</strong>：深求隐僻之理、行为诡异，后世或许有人称述，我却不做。</p><p><strong>遵道而行 · 半涂而废</strong>：君子依道而行，却半路停下，我不能这样。</p><p><strong>依乎中庸 · 遁世不见知而不悔</strong>：君子依循中庸，避世而不被了解也不后悔——这只有圣人能做到。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十一章是一组三连：</p><ul><li><strong>索隐行怪</strong>——走偏求异，或能得后世之名，孔子说他不做</li><li><strong>半涂而废</strong>——依道而行却半路停下，孔子说他不肯</li><li><strong>依乎中庸，遁世不见知而不悔</strong>——只有圣人做得到</li></ul><p>前两者，正是第四章「过之」与「不及」的具体模样。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>朱注把两种偏差判得极准</strong>：索隐行怪是「<strong>不当强而强</strong>」（不该使劲的地方使劲），半涂而废是「<strong>当强而不强</strong>」（该坚持时松手）。一过一不及，对症下药。</li><li><strong>它指出两个常见的失败</strong>：一种是<strong>求异</strong>（为与众不同的名），一种是<strong>半途</strong>（力不足）。前者问题在心，后者问题在力。</li><li><strong>「不见知而不悔」是极高的标的</strong>：朱注说这是「中庸之成德，知之尽、仁之至、不赖勇而裕如者」——不用靠勇，从容而足。与第 3 章「民鲜能久」、第 9 章「不可能」连起来看，全篇一直在说同一件事：<strong>难的是持守到底，且不求人知</strong>。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>防「索隐行怪」</strong>：把「不一样」当成价值，就是走偏的开始。</li><li><strong>防「半涂而废」</strong>：不是没择对，是没走完；力气不足是真实原因，先补力气。</li><li><strong>防「求人知」</strong>：做给自己看的那部分，才是「不见知而不悔」。</li><li><strong>两种偏差要分开治</strong>：过与不及的根不同，别用一个办法去解。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>这一章对比三种活法。</p><p>第一种是<strong>求异</strong>：专挑隐僻诡异的来走，图后世的名声。孔子说不干。 第二种是<strong>半途</strong>：路子选对了，走一半停下了。孔子说不肯。 第三种是<strong>依乎中庸</strong>：按中道走，哪怕全世界都不知道、都不认可，也不后悔——孔子说，这只有圣人做得到。</p><p>朱子的判语很利落：第一种是<strong>不该使劲时使劲</strong>，第二种是<strong>该坚持时松手</strong>。一个「过」，一个「不及」，都是离开了中。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「索隐行怪」（过）与「半涂而废」（不及）——我更常犯哪一种？</li><li>「遁世不见知而不悔」——如果一件事永远不会有人知道，我还会做吗？</li><li>朱注说索隐行怪是「不当强而强」、半涂而废是「当强而不强」——我最近在哪件事上使劲使错了地方？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-10">中庸·第10章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-12">中庸·第12章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{c as __pageData,f as default};
